-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per client payment received, voided ones included (see IsVoided). Needs invoice.view.
CREATE VIEW rpt.Payment
AS
SELECT
    pay.Id AS PaymentId,
    pay.PaymentDate AS PaymentDate,
    pay.ClientId AS ClientId,
    c.Name AS ClientName,
    pm.Name AS PaymentMethod,
    pay.ReferenceNumber AS ReferenceNumber,
    pay.Amount AS Amount,
    pay.AmountApplied AS AmountApplied,
    pay.AmountRefunded AS AmountRefunded,
    pay.UnappliedAmount AS UnappliedAmount,
    CONVERT(BIT, IIF(pay.VoidedAt IS NULL, 0, 1)) AS IsVoided
FROM ar.InvoicePay AS pay
JOIN crm.Client AS c ON c.TenantId = pay.TenantId AND c.Id = pay.ClientId
JOIN lkp.PaymentMethod AS pm ON pm.TenantId = pay.TenantId AND pm.Id = pay.PaymentMethodId
WHERE EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(pay.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'invoice.view'));
GO
